"""Render only retained fictional exercise results into an offline, script-free report."""
from html import escape

def render(summary):
 c=summary['exercises']['capacity'];m=summary['exercises']['material-quality'];counts=m['final_counts'];fractions=m['exact_fractions']
 def table(caption,rows):return '<table><caption>'+escape(caption)+'</caption><tbody>'+''.join('<tr><th scope="row">'+escape(label)+'</th><td>'+escape(str(value))+'</td></tr>' for label,value in rows)+'</tbody></table>'
 def receipt_table(folder,value):
  return '<details><summary>Inspect '+str(value['command_checks'])+' retained command receipts</summary><table><caption>Actual CLI outcomes and exact saved files</caption><thead><tr><th>Check</th><th>Outcome</th><th>Files</th></tr></thead><tbody>'+''.join('<tr><th scope="row">'+escape(row['case'])+'</th><td><span class="'+('review' if row['exit_code'] else 'pass')+'">'+('REVIEW_REQUIRED' if row['exit_code'] else 'PASS')+'</span></td><td><a href="'+folder+'/'+escape(row['case'])+'-input.json">Input</a> · <a href="'+folder+'/'+escape(row['case'])+'-report.json">Report</a></td></tr>' for row in value['receipts'])+'</tbody></table></details>'
 style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#121315;color:#eeeae0;font:16px/1.6 "Segoe UI",Arial,sans-serif}a{color:#8cdbca;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #ffce75;outline-offset:5px}.shell{width:min(1120px,90%);margin:auto}header{padding:25px 0;border-bottom:1px solid #35383c}.brand{font-size:14px;letter-spacing:2px;font-weight:700}nav{display:flex;flex-wrap:wrap;gap:12px 25px;margin-top:15px;font-size:14px}h1{font-size:clamp(38px,6vw,66px);line-height:1.08;letter-spacing:-2px;margin:25px 0}h2{font-size:32px;line-height:1.2}h3{font-size:21px}.eyebrow{color:#8cdbca;text-transform:uppercase;letter-spacing:2px;font-size:12px}.hero{padding:50px 0 30px}.lead{max-width:760px;color:#c0c3c7}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:35px 0}.metric{border-top:1px solid #41464d;padding-top:15px;color:#b6b9bd;font-size:14px}.metric strong{display:block;color:#eeeae0;font-size:40px;line-height:1.2}.status{padding:18px 22px;background:#193731;border:1px solid #38746a;border-radius:8px}.status strong{color:#8cdbca}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}section{padding:32px 0;border-top:1px solid #35383c;scroll-margin-top:20px}.panel{background:#1b1d20;border:1px solid #35383c;border-radius:10px;padding:25px;min-width:0}.panel p{color:#c0c3c7}table{border-collapse:collapse;width:100%;font-size:14px;margin:20px 0}caption{text-align:left;color:#aab0b7;font-size:12px;margin-bottom:12px}th,td{text-align:left;padding:12px 6px;border-bottom:1px solid #34383d;vertical-align:top;overflow-wrap:anywhere}th{font-weight:600;width:48%}td{color:#ccd0d5}.pass{color:#8cdbca}.review{color:#ffca7e}summary{cursor:pointer;color:#eeeae0;padding:16px 0}details{margin-top:20px;border-top:1px solid #41464d}.note{font-size:13px;color:#aeb5be}.equation{font-size:clamp(24px,3vw,38px);font-weight:700;color:#8cdbca}.receipt-label{font-size:12px;text-transform:uppercase;letter-spacing:1px}footer{padding:30px 0 50px;color:#aab0b7;font-size:13px}@media(max-width:700px){.grid,.metrics{grid-template-columns:1fr}h1{letter-spacing:-1px}.hero{padding-top:28px}.panel{padding:19px}th{width:45%}}'''
 head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Manufacturing Review — retained results</title><style>'''+style+'''</style></head><body><header class="shell"><div class="brand">OUTLANDS / MANUFACTURING REVIEW</div><nav aria-label="Report sections"><a href="#overview">Overview</a><a href="#capacity">Capacity</a><a href="#materials">Materials</a><a href="#inspection">Inspection</a><a href="#outcomes">Outcomes</a><a href="#evidence">Evidence</a></nav></header><main class="shell">'''
 overview='''<div class="hero" id="overview"><p class="eyebrow">ACTUAL LOCAL RUN / INVENTED DECLARATIONS</p><h1>Follow the workflow.<br>Keep the failed result.</h1><p class="lead">Two fictional exercises connect capacity and process accounting with canonical lots, inspection coverage and selected rework outcomes. This page reads the results of this run; it does not operate a production system.</p><div class="metrics"><div class="metric"><strong>36</strong>Original CLI checks reproduced</div><div class="metric"><strong>17</strong>Expected REVIEW_REQUIRED outcomes retained</div><div class="metric"><strong>2</strong>Existing exercises, unchanged source</div></div><div class="status"><strong>Run complete — all expected checks reproduced.</strong><br>A successful exercise retains the expected failures. Operator review remains REQUIRED.</div></div>'''
 capacity='<section id="capacity"><p class="eyebrow">01 / CAPACITY AND PROCESS</p><h2>Eligible individually. Over capacity together.</h2><div class="grid"><article class="panel"><h3>Check the combination.</h3><p>Correcting the missing capability makes three proposals individually eligible. Their combined station reservation still exceeds capacity two. A separately authored start-at-six revision removes the overlap.</p>'+table('Actual fictional capacity results',[('Individual eligibility',str(c['eligible_before'])+' → '+str(c['eligible_after'])+' of 3'),('Combined peak',str(c['peak_units_before'])+' → '+str(c['peak_units_after'])+' / capacity '+str(c['capacity'])),('Conflict span','[3,6); adjacent end/start at 6 do not overlap')])+'</article><article class="panel"><h3>Keep incomplete runs visible.</h3><p>Missing finish events withhold durations. A complete supplied history accounts for active and held ticks separately. Declared quantities must reconcile; a one-piece mismatch remains beside its corrected proposal.</p>'+table('Actual fictional duration and flow results',[('Elapsed ticks',c['duration_ticks']['elapsed_ticks']),('Active + held',str(c['duration_ticks']['active_ticks'])+' + '+str(c['duration_ticks']['hold_ticks'])),('Reconciled closing',str(c['stock_closing'])+' stock + '+str(c['wip_closing'])+' WIP = '+str(c['total_closing'])),('Initial WIP discrepancy',c['initial_flow_delta'])])+'</article></div>'+receipt_table('capacity',c)+'</section>'
 materials='<section id="materials"><p class="eyebrow">02 / MATERIAL REQUIREMENTS AND IDENTITIES</p><h2>Two labels are still one lot.</h2><div class="grid"><article class="panel"><h3>Count canonical stock once.</h3><p>A cyclic BOM and conflicting quantity under one lot ID withhold results. After correction, two labels resolve to the same canonical motor lot. The labels do not add more stock.</p>'+table('Actual fictional material accounting',[('Kits',m['kits']),('Motor requirement / stock',str(m['motor_requirement'])+' / '+str(m['canonical_motor_stock'])),('Filter requirement',m['filter_requirement']),('Overreserved motor units',m['overreserved_motor_units']),('Initial filter shortage',m['filter_shortage_before'])])+'</article><article class="panel"><h3>Consistency is not delivery.</h3><p>Two alias-based claims initially reserve five motors from four available. A corrected proposal reserves four motors and eight filters. A three-piece receipt against four withholds totals; the corrected receipt accounts for four.</p><p class="equation">2 + 3 against 4</p><p>Identical repeated identities count once. Distinct canonical IDs cannot establish whether physical stock was counted twice.</p><p class="note">No inventory, reservation or transfer is changed.</p></article></div></section>'
 inspection='<section id="inspection"><p class="eyebrow">03 / INSPECTION COVERAGE AND OUTCOMES</p><h2>Complete records can still fail.</h2><div class="grid"><article class="panel"><h3>Keep the missing record.</h3><p>One of four required records is missing initially. Adding the fourth makes coverage complete, while two readings remain outside the teaching rule [1,3).</p>'+table('Actual fictional inspection selections',[('Initial coverage','3 of 4; '+str(m['coverage_missing_before'])+' missing'),('Complete initial selection','4 records / '+str(m['initial_within_limits'])+' within / 2 outside'),('Selected later reading','4 records / '+str(m['later_within_limits'])+' within / 1 outside')])+'</article><article class="panel"><h3>Keep the failed outcome.</h3><p>Initial values 2 and 1 are within; 3 and 0 are outside. A separately selected later value of 2 changes the third specimen. The fourth remains outside and is retained in the authored scrap history.</p><p>These are arbitrary demo-units, not equipment specifications or calibrated readings. Hashes pin the saved reports; they do not prove truthful measurements.</p><p class="note">The coverage tool never opens evidence bytes. This launcher independently rechecks the retained report hashes.</p></article></div></section>'
 outcomes='<section id="outcomes"><p class="eyebrow">04 / SELECTED REWORK AND SCRAP OUTCOMES</p><h2>Explain the denominator.</h2><div class="grid"><article class="panel"><h3>One selected outcome per specimen.</h3><p>Incorrect reinspection attempts withhold the history. Contradictory dispositions withhold yield counts. The corrected teaching protocol records five inspection attempts and one rework event.</p><p class="equation">'+str(counts['first_pass_good'])+' + '+str(counts['reworked_good'])+' + '+str(counts['scrap'])+' = '+str(counts['cohort'])+'</p><p>First-pass good + reworked good + scrap. A reworked specimen contributes one good unit.</p></article><article class="panel"><h3>Keep exact cohort fractions.</h3>'+table('Actual fictional outcome accounting',[('First-pass fraction',fractions['first_pass_yield']),('Eventual good',fractions['eventual_yield']),('Scrap fraction',fractions['scrap_fraction']),('Separate pending variant',m['pending_fraction']+'; denominator stays four')])+'<p class="note">A consistent closed cohort passes reconciliation. No quality target or real-world acceptance is judged.</p></article></div></section>'
 evidence='<section id="evidence"><p class="eyebrow">05 / PRESERVED INPUTS AND REVIEW EVIDENCE</p><h2>Inspect the original reports.</h2><p>Every command retains its original input, exact CLI report, exit code and independently recomputed SHA-256. All earlier diagnostics remain beside the corrected selections. No report is silently replaced.</p>'+receipt_table('material-quality',m)+'<p><a href="result.json">Both observed exercise summaries</a> · <a href="RUN-MANIFEST.json">This run’s file hashes</a> · <a href="material-quality/authored-mapping.json">Explicit report mappings</a></p><p class="note">Run the launcher again for a new independent folder. Keep this folder to inspect or reopen it; --open verifies its saved file hashes without rerunning the exercises. Hashes establish byte consistency, not authenticity or permission to share.</p></section>'
 footer='</main><footer class="shell">Manufacturing Review Demo 0.1.0 / Python 3.14.10 included / Original source '+escape(summary['source_revision'][:12])+'.<br>Fictional records only. No work is assigned; no stock, transfer, inspection, repair or physical traceability is verified. This report does not grant operating or publication authority. Keep actual operational data private.</footer></body></html>'
 return head+overview+capacity+materials+inspection+outcomes+evidence+footer
